"""deskstats.timeparse: the one place where times are read."""

import ast
import os
import subprocess
import sys
import unittest
from datetime import date, datetime, timedelta, timezone
from pathlib import Path

from deskstats import timeparse as tp

PLUS1 = timezone(timedelta(hours=1))
ROOT = Path(__file__).resolve().parent.parent


class Offset(unittest.TestCase):
    def test_offsets(self):
        self.assertEqual(tp.parse_offset("+05:30"), timezone(timedelta(hours=5, minutes=30)))
        self.assertEqual(tp.parse_offset("-08:00").utcoffset(None), timedelta(hours=-8))
        self.assertEqual(tp.parse_offset("+00:00"), timezone.utc)

    def test_bad_offsets(self):
        for text in ["+0100", "01:00", "+1:00", " +01:00", "+01:00 ", "+24:00", "+99:99", ""]:
            with self.subTest(text=text), self.assertRaises(ValueError):
                tp.parse_offset(text)


class Instant(unittest.TestCase):
    def test_naive_gets_zone(self):
        self.assertEqual(tp.parse_instant(" 2026-03-02T09:15:02 ", tp.UTC), datetime(2026, 3, 2, 9, 15, 2, tzinfo=tp.UTC))
        self.assertEqual(tp.parse_instant("2026-03-02T09:15", PLUS1).utcoffset(), timedelta(hours=1))

    def test_offset_kept(self):
        t = tp.parse_instant("2026-03-02T10:15:02.250+05:30", PLUS1)
        self.assertEqual(t.utcoffset(), timedelta(hours=5, minutes=30))
        self.assertEqual(t.microsecond, 250000)
        self.assertEqual(tp.parse_instant("20260302T101502Z", PLUS1).utcoffset(), timedelta(0))

    def test_layouts(self):
        layouts = ("%Y-%m-%d %H:%M", "%d.%m.%Y %H:%M")
        self.assertEqual(tp.parse_instant("2026-3-2 9:05", PLUS1, layouts), datetime(2026, 3, 2, 9, 5, tzinfo=PLUS1))
        self.assertEqual(tp.parse_instant("02.03.2026 9:05", PLUS1, layouts), datetime(2026, 3, 2, 9, 5, tzinfo=PLUS1))
        with self.assertRaises(ValueError):
            tp.parse_instant("02.03.2026 9:05", PLUS1)
        with self.assertRaises(ValueError):
            tp.parse_instant("later", PLUS1, layouts)


class Epoch(unittest.TestCase):
    def test_truncate(self):
        want = datetime(2026, 3, 2, 9, 15, 2, tzinfo=tp.UTC)
        self.assertEqual(tp.from_epoch("1772442902.75", tp.SECONDS, tp.TRUNCATE), want)
        self.assertEqual(tp.from_epoch(1772442902.99, tp.SECONDS, tp.TRUNCATE), want)
        self.assertEqual(tp.from_epoch("-0.5", tp.SECONDS, tp.TRUNCATE), datetime(1970, 1, 1, tzinfo=tp.UTC))
        self.assertEqual(tp.from_epoch(1772442902999, tp.MILLIS, tp.TRUNCATE), want)

    def test_nearest_even(self):
        def at(ms):
            return tp.from_epoch(ms, tp.MILLIS, tp.NEAREST_EVEN)

        base = datetime(1970, 1, 1, tzinfo=tp.UTC)
        self.assertEqual(at(500), base)
        self.assertEqual(at(1500), base + timedelta(seconds=2))
        self.assertEqual(at(2500), base + timedelta(seconds=2))
        self.assertEqual(at(-1500), base - timedelta(seconds=2))
        self.assertEqual(at(1772442902750), datetime(2026, 3, 2, 9, 15, 3, tzinfo=tp.UTC))
        self.assertEqual(at("1772442902250"), datetime(2026, 3, 2, 9, 15, 2, tzinfo=tp.UTC))

    def test_bad_values(self):
        for value in ["soon", "", "nan", "inf", "1e400", "1e30", "1e17", None, True, [1]]:
            with self.subTest(value=value), self.assertRaises(ValueError):
                tp.from_epoch(value, tp.SECONDS, tp.TRUNCATE)

    def test_unknown_names(self):
        with self.assertRaises(ValueError):
            tp.from_epoch(1, "us", tp.TRUNCATE)
        with self.assertRaises(ValueError):
            tp.from_epoch(1, tp.SECONDS, "floor")


class Day(unittest.TestCase):
    def test_ymd(self):
        self.assertEqual(tp.parse_day("2026-03-06", tp.YMD), date(2026, 3, 6))
        self.assertEqual(tp.parse_day("20260306", tp.YMD), date(2026, 3, 6))
        with self.assertRaises(ValueError):
            tp.parse_day("06/03/2026", tp.YMD)

    def test_dmy(self):
        self.assertEqual(tp.parse_day("09/03/26", tp.DMY), date(2026, 3, 9))
        self.assertEqual(tp.parse_day("9/3/2026", tp.DMY), date(2026, 3, 9))
        self.assertEqual(tp.parse_day("1/1/0", tp.DMY), date(2000, 1, 1))
        self.assertEqual(tp.parse_day("1/1/-5", tp.DMY), date(1995, 1, 1))
        for text in ["1/1", "1/1/1/1", "31/02/26", "1-1-26", "a/b/c", "1/1/99999999999999999999"]:
            with self.subTest(text=text), self.assertRaises(ValueError):
                tp.parse_day(text, tp.DMY)

    def test_mdy(self):
        self.assertEqual(tp.parse_day("03/08/2026", tp.MDY), date(2026, 3, 8))
        self.assertEqual(tp.parse_day("3/8/2026", tp.MDY), date(2026, 3, 8))
        for text in ["13/01/2026", "03/08/26", "2026-03-08", "02/30/2026"]:
            with self.subTest(text=text), self.assertRaises(ValueError):
                tp.parse_day(text, tp.MDY)

    def test_unknown_order(self):
        with self.assertRaises(ValueError):
            tp.parse_day("2026-03-06", "ydm")


class Clock(unittest.TestCase):
    DAY = date(2026, 3, 2)

    def test_clock(self):
        self.assertEqual(tp.at_clock(self.DAY, "22:05", PLUS1), datetime(2026, 3, 2, 22, 5, tzinfo=PLUS1))
        self.assertEqual(tp.at_clock(self.DAY, "9:5", PLUS1), datetime(2026, 3, 2, 9, 5, tzinfo=PLUS1))

    def test_midnight_24(self):
        self.assertEqual(tp.at_clock(self.DAY, "24:00", PLUS1), datetime(2026, 3, 3, 0, 0, tzinfo=PLUS1))
        self.assertEqual(tp.at_clock(date(2026, 12, 31), "24:00", PLUS1), datetime(2027, 1, 1, tzinfo=PLUS1))

    def test_bad_clock(self):
        for text in ["24:01", "25:00", "12:60", "1200", "1:2:3", "-1:00", "noon", ""]:
            with self.subTest(text=text), self.assertRaises(ValueError):
                tp.at_clock(self.DAY, text, PLUS1)
        with self.assertRaises(ValueError):
            tp.at_clock(date.max, "24:00", PLUS1)

    def test_day_start(self):
        self.assertEqual(tp.day_start(self.DAY, PLUS1), datetime(2026, 3, 2, tzinfo=PLUS1))
        self.assertIs(tp.day_start(self.DAY, PLUS1).tzinfo, PLUS1)


class Isolation(unittest.TestCase):
    def test_zone_of_the_machine_is_irrelevant(self):
        code = (
            "from deskstats import timeparse as tp\n"
            "print(tp.from_epoch('1772442902.75', tp.SECONDS, tp.TRUNCATE).isoformat())\n"
            "print(tp.from_epoch(-1500, tp.MILLIS, tp.NEAREST_EVEN).isoformat())\n"
            "print(tp.parse_instant('2026-03-02T09:15', tp.UTC).isoformat())\n"
        )
        seen = set()
        for tz in ["UTC", "America/New_York", "Asia/Kolkata", "Pacific/Auckland"]:
            env = {**os.environ, "TZ": tz, "PYTHONDONTWRITEBYTECODE": "1"}
            r = subprocess.run([sys.executable, "-c", code], cwd=ROOT, env=env, capture_output=True, text=True)
            self.assertEqual(r.returncode, 0, r.stderr)
            seen.add(r.stdout)
        self.assertEqual(len(seen), 1)

    def test_only_timeparse_builds_times(self):
        banned_calls = {"strptime", "fromisoformat", "fromtimestamp", "utcfromtimestamp", "fromordinal", "fromisocalendar",
                        "combine", "timestamp", "datetime", "date", "time", "timezone"}
        banned_modules = {"time", "calendar", "email.utils"}
        for path in sorted((ROOT / "deskstats").glob("*.py")):
            if path.name == "timeparse.py":
                continue
            tree = ast.parse(path.read_text(encoding="utf-8"))
            for node in ast.walk(tree):
                where = f"{path.name}:{getattr(node, 'lineno', 0)}"
                if isinstance(node, ast.Call):
                    f = node.func
                    name = f.attr if isinstance(f, ast.Attribute) else f.id if isinstance(f, ast.Name) else ""
                    self.assertNotIn(name, banned_calls, where)
                    if name == "replace":
                        self.assertFalse(node.keywords and {k.arg for k in node.keywords} - {None} & {"tzinfo", "year", "month", "day", "hour", "minute", "second", "microsecond"}, where)
                if isinstance(node, ast.Import):
                    self.assertFalse({a.name for a in node.names} & banned_modules, where)
                if isinstance(node, ast.ImportFrom):
                    self.assertNotIn(node.module, banned_modules, where)

    def test_imports_nothing_from_deskstats(self):
        tree = ast.parse((ROOT / "deskstats" / "timeparse.py").read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom):
                self.assertFalse((node.module or "").startswith("deskstats"))
            if isinstance(node, ast.Import):
                self.assertFalse(any(a.name.startswith("deskstats") for a in node.names))


if __name__ == "__main__":
    unittest.main()

